mapper.select:
SELECT COALESCE(SUM(
    CASE
        WHEN txn_type = 'IN' THEN quantity
        WHEN txn_type = 'OUT' THEN -quantity
        ELSE 0
    END
), 0)
FROM goods_transaction_dynamic_info
WHERE warehouse_id = #{warehouseId}
  AND material_id = #{materialId}

mapper.update:
UPDATE goods_transaction_dynamic_info
material_id = #{materialId}, material_code = #{materialCode}, material_name = #{materialName}, model = #{model}, brand = #{brand}, category = #{category}, project_id = #{projectId}, warehouse_id = #{warehouseId}, txn_type = #{txnType}, txn_time = #{txnTime}, quantity = #{quantity}, unit_price = #{unitPrice}, amount = #{amount}, source_ref_type = #{sourceRefType}, source_ref_id = #{sourceRefId}, update_time = NOW(), update_user = #{updatedBy}
WHERE uuid = #{uuid}

mapper.delete:
DELETE FROM goods_transaction_dynamic_info
WHERE source_ref_type = #{sourceRefType}
  AND source_ref_id = #{sourceRefId}
